using System.Collections;
using System.Linq;
using UnityEngine;


namespace SOSXR.Talkies
{
    /// <summary>
    ///     A class that keeps track of which pins have been used by the PinController, and sets those LOW after a short time interval
    ///     This to try to keep heat generated by some components to minimum.
    ///     Only pins that were actually set through the <see cref="PinController" /> are touched.
    /// </summary>
    [RequireComponent(typeof(PinController))]
    public class SafetyPin : MonoBehaviour
    {
        [SerializeField] [Range(1, 60)] private int m_setLowAfterSeconds = 30;
        [SerializeField] [HideInInspector] private PinController _pinController;
        private readonly float _checkDelay = 1f;

        private readonly PinDeadlineTracker _tracker = new();


        /// <summary>The pins this component knows about and their deadlines.</summary>
        public PinDeadlineTracker Tracker => _tracker;


        private PinController Controller
        {
            get
            {
                if (_pinController == null)
                {
                    _pinController = GetComponent<PinController>();
                }

                return _pinController;
            }
        }


        private void OnValidate()
        {
            if (_pinController == null)
            {
                _pinController = GetComponent<PinController>();
            }
        }


        private void OnEnable()
        {
            if (Controller != null)
            {
                Controller.OnPinSetEvent += StartTimer;
            }

            StartCoroutine(TimeCheckerCR());
        }


        private void Start()
        {
            Debug.Log($"{nameof(SafetyPin)} is initialized. It will turn used pins LOW after {m_setLowAfterSeconds} seconds.");
        }


        /// <summary>
        ///     Called whenever a pin is SET via <see cref="PinController" />. Starts a countdown
        ///     timer for pins driven HIGH; resets the timer when a pin is driven LOW.
        ///     The timer is only started once per pin — refreshing HIGH will not reset the countdown.
        /// </summary>
        /// <param name="pinNumber">GPIO pin number being set.</param>
        /// <param name="value"><c>true</c> when the pin is driven HIGH; <c>false</c> when LOW.</param>
        private void StartTimer(int pinNumber, bool value)
        {
            _tracker.OnPinSet(pinNumber, value, Time.time, m_setLowAfterSeconds);
        }


        private IEnumerator TimeCheckerCR()
        {
            var wait = new WaitForSeconds(_checkDelay);

            for (;;)
            {
                yield return wait;

                foreach (var pin in _tracker.CollectExpired(Time.time))
                {
                    Debug.Log($"Setting pin {pin} to LOW because it has been too HIGH for too long.");

                    if (Controller != null)
                    {
                        Controller.SetPin(pin, false);
                    }
                }
            }
        }


        /// <summary>
        ///     Immediately drives every tracked pin LOW, regardless of their timer state.
        ///     Called on disable to ensure hardware is left in a safe state.
        /// </summary>
        private void HardDisableAllKnownPins()
        {
            if (Controller == null || !Controller.IsConnected)
            {
                return;
            }

            foreach (var pin in _tracker.KnownPins.ToArray())
            {
                Controller.SetPin(pin, false);
            }
        }


        private void OnDisable()
        {
            HardDisableAllKnownPins();

            if (_pinController != null)
            {
                _pinController.OnPinSetEvent -= StartTimer;
            }

            StopAllCoroutines();
        }
    }
}
